package com.lqq.supportflow.knowledge.api;
import com.lqq.supportflow.knowledge.application.CreateKnowledgeBaseService; import com.lqq.supportflow.knowledge.domain.KnowledgeBase; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import jakarta.validation.Valid; import java.net.URI; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/knowledge-bases") public class AdminKnowledgeBaseController { private final CreateKnowledgeBaseService service; public AdminKnowledgeBaseController(CreateKnowledgeBaseService service){this.service=service;}
 @PostMapping ResponseEntity<KnowledgeBase> create(@AuthenticationPrincipal AuthenticatedPrincipal p,@Valid @RequestBody CreateKnowledgeBaseRequest r){KnowledgeBase b=service.create(p.tenantId(),r.name(),r.description());return ResponseEntity.created(URI.create("/api/v1/admin/knowledge-bases/"+b.id())).body(b);}}
